using System;using System.Net.Http;using Newtonsoft.Json.Linq;
public class CPHInline{string A(string k){try{return args.ContainsKey(k)&&args[k]!=null?args[k].ToString():"";}catch{return "";}}
public bool Execute(){string mode=A("spotifyLookupMode");try{using(var c=new HttpClient()){c.Timeout=TimeSpan.FromSeconds(8);var r=c.GetAsync("http://127.0.0.1:3127/api/spotify/current").GetAwaiter().GetResult();if(!r.IsSuccessStatusCode){CPH.LogWarn("[spotify-chat] Companion returned HTTP "+(int)r.StatusCode);return true;}JObject p=JObject.Parse(r.Content.ReadAsStringAsync().GetAwaiter().GetResult());bool enabled=mode=="playlist"?(bool?)p["playlistCommandEnabled"]??false:(bool?)p["songCommandEnabled"]??false;if(!enabled)return true;string text=mode=="playlist"?(string)p["playlistText"]:(string)p["songText"];if(String.IsNullOrWhiteSpace(text))return true;CPH.SetArgument("chatMessage",mode=="playlist"?"Current playlist: "+text:"Current song: "+text);CPH.SetArgument("chatReplyId",A("msgId"));CPH.SetArgument("chatReplyUser",A("userName"));CPH.SetArgument("chatIsReply",!String.IsNullOrWhiteSpace(A("msgId")));CPH.SetArgument("chatTargets","all");CPH.RunAction("Chat - All Platforms",true);}}catch(Exception ex){CPH.LogWarn("[spotify-chat] "+ex.Message);}return true;}}